Implemented as a memoized digit DP over the decimal representation with a
tight-bound flag; the range [a, b] itself is never iterated.
"""

from functools import lru_cache


def _count_upto(n: int, k: int) -> int:
    """Count integers in [0, n] with digit sum % k == 0."""
    if n < 0:
        return 0
    digits = list(map(int, str(n)))

    @lru_cache(maxsize=None)
    def dp(pos: int, remainder: int, tight: bool) -> int:
        if pos == len(digits):
            return 1 if remainder == 0 else 0
        limit = digits[pos] if tight else 9
        total = 0
        for d in range(limit + 1):
            total += dp(pos + 1, (remainder + d) % k, tight and d == limit)
        return total

    return dp(0, 0, True)


def count(a: int, b: int, k: int) -> int:
    """How many integers x with a <= x <= b have digit sum divisible by k."""
    if a > b:
        raise ValueError("require a <= b")
    if k < 1:
        raise ValueError("require k >= 1")
    return _count_upto(b, k) - _count_upto(a - 1, k)
