import time

import pytest

from digit_dp import count


def brute(a: int, b: int, k: int) -> int:
    return sum(1 for x in range(a, b + 1) if sum(int(d) for d in str(x)) % k == 0)


def test_random_battery():
    rng = random.Random(20260824)
    cases = [(rng.randint(0, 10**6), rng.randint(0, 10**6), rng.randint(1, 9))
             for _ in range(500)]
    for a, b, k in cases:
        lo, hi = min(a, b), max(a, b)
        assert count(lo, hi, k) == brute(lo, hi, k), (lo, hi, k)


def test_a_equals_b():
    for k in range(1, 10):
        for x in (0, 1, 7, 9, 18, 99, 12345, 999_999):
            expected = 1 if sum(map(int, str(x))) % k == 0 else 0
            assert count(x, x, k) == expected, (x, k)


def test_a_zero():
    for k in range(1, 10):
        for b in (0, 1, 10, 57, 1000, 123_456, 10**6):
            assert count(0, b, k) == brute(0, b, k), (b, k)


def test_k_one_is_full_range():
    for a, b in [(0, 1), (5, 5), (13, 777), (0, 10**6)]:
        assert count(a, b, 1) == b - a + 1, (a, b)


